#include "../ring3_common.hpp"
static constexpr u32 W=560,H=380; static u32*pix; static u64 events,win; static bool dirty=true; static char input[96]; static u32 n;
static void draw(){fill(pix,W*H,0x00f3f6f9);rect(pix,W,H,0,0,W,52,0x002a5f9e);text(pix,W,H,18,17,"SKY DEFENDER",0x00ffffff,2);rect(pix,W,H,18,70,W-36,42,0x00ffffff);text(pix,W,H,30,85,"SCORE 0   READY",0x00182030,1);rect(pix,W,H,18,128,W-36,H-166,0x00ffffff);text(pix,W,H,34,150,"RING 3 GAME",0x00485465,1);if(input[0])text(pix,W,H,34,184,input,0x00182030,1);text(pix,W,H,20,H-22,"ISOLATED APPLICATION PROCESS",0x00485465,1);sc(SYS_PRESENT,win,(u64)pix,(u64)W*H*4);dirty=false;}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);if(!pix)sc(0,1);win=makeWindow(events,W,H,220,110);if(!win)sc(0,2);for(;;){Wire m{};while(sc(SYS_IPC_RECV,events,(u64)&m)>0){if(m.type==KEY&&m.bytes==sizeof(KeyEv)){char c=(char)((KeyEv*)m.payload)->codepoint;if(c=='\b'){if(n)input[--n]=0;}else if(c>=32&&c<127&&n<94){input[n++]=c;input[n]=0;}dirty=true;}else if(m.type==CLOSE)sc(0,0);}if(dirty)draw();sc(SYS_YIELD);}}
